CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS "user" ("id" text PRIMARY KEY, "name" text NOT NULL, "email" text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, "image" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" ("id" text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, "token" text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "account" ("id" text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"("id") ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "verification" ("id" text PRIMARY KEY, "identifier" text NOT NULL, "value" text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, title text NOT NULL, concept text NOT NULL DEFAULT '', format text NOT NULL DEFAULT 'Story', "durationSeconds" numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'DRAFT', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS characters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "projectId" uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', appearance text NOT NULL DEFAULT '', voice text NOT NULL DEFAULT '', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scenes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "projectId" uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, "sceneNumber" integer NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', dialogue text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', "timeOfDay" text NOT NULL DEFAULT '', "durationSeconds" numeric NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS scenes_project_scene_number_unique ON scenes("projectId", "sceneNumber");
CREATE TABLE IF NOT EXISTS media_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "projectId" uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, "sceneId" uuid REFERENCES scenes(id) ON DELETE SET NULL, kind text NOT NULL, pathname text NOT NULL, "contentType" text NOT NULL, "durationSeconds" numeric, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS generation_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "projectId" uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, "sceneId" uuid REFERENCES scenes(id) ON DELETE SET NULL, type text NOT NULL, status text NOT NULL DEFAULT 'QUEUED', progress integer NOT NULL DEFAULT 0, stage text NOT NULL DEFAULT 'Queued', attempts integer NOT NULL DEFAULT 0, error text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, "idempotencyKey" text, result jsonb, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS generation_jobs_project_idempotency_unique ON generation_jobs("projectId", "idempotencyKey") WHERE "idempotencyKey" IS NOT NULL;
CREATE TABLE IF NOT EXISTS generation_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "jobId" uuid NOT NULL REFERENCES generation_jobs(id) ON DELETE CASCADE, "eventType" text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, "availableAt" timestamptz NOT NULL DEFAULT now(), "lockedAt" timestamptz, "processedAt" timestamptz, "lastError" text, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS generation_outbox_job_event_unique ON generation_outbox("jobId", "eventType");
CREATE INDEX IF NOT EXISTS generation_outbox_pending_idx ON generation_outbox(status, "availableAt");
CREATE INDEX IF NOT EXISTS projects_user_updated_idx ON projects("userId", "updatedAt");
CREATE INDEX IF NOT EXISTS scenes_project_number_idx ON scenes("projectId", "sceneNumber");
CREATE INDEX IF NOT EXISTS media_assets_project_created_idx ON media_assets("projectId", "createdAt");
CREATE INDEX IF NOT EXISTS generation_jobs_project_status_idx ON generation_jobs("projectId", status, "createdAt");
